const b = $input.first().json.body || $input.first().json;
const email = String(b.email || "").trim().toLowerCase();
const domain = email.includes("@") ? email.split("@")[1] : "";
const freeDomains = new Set(["gmail.com", "yahoo.com", "hotmail.com", "outlook.com", "icloud.com", "proton.me"]);
return [{
  json: {
    name: String(b.name || "Unknown").trim(),
    email,
    company: String(b.company || domain || "Unknown").trim(),
    website: String(b.website || (domain && !freeDomains.has(domain) ? `https://${domain}` : "")).trim(),
    isCorporateEmail: Boolean(domain && !freeDomains.has(domain)),
    message: String(b.message || "").slice(0, 1500),
    receivedAt: new Date().toISOString(),
  }
}];

const lead = $('Normalize Lead Payload').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
let ai = { score: 0, tier: 'COLD', summary: 'Parse fallback', recommendedNextAction: 'Review manually', personalizedOpeningLine: '' };
try { ai = { ...ai, ...JSON.parse(raw) }; } catch {}
return [{ json: { ...lead, ...ai, score: Number(ai.score) || 0 } }];
